// Таблица синонимов ключей для бесшовной совместимости с вызовами в ui.js и engine.js
const KEY_ALIASES = {
  pal_unlock_matrix_green: 'pal_unlock_t10',
  pal_unlock_t10_free: 'pal_unlock_t10',
  pal_unlock_cyber_gold: 'pal_unlock_prem_t1',
  pal_unlock_blood_moon: 'pal_unlock_prem_t30',
  free_theme_unlocks_t10: 'pal_free_t10_toast',
  reach_tier_first: 'reach_tier_n_first',
  activate_premium_first: 'activate_prem_first',
  unlocked_palette: 'unlocked_palette_toast',
  perk_starting_reserve_unlocked: 'unlocked_perk_gold',
  ultimate_bp_reward_claimed: 'ultimate_reward_claimed',
  premium_already_activated: 'prem_already_active',
  synth_pass_premium_activated: 'prem_activated_toast',
  synth_pass_max_tier: 'bp_already_max',
  tier_purchased_plus_100_xp: 'tier_purchased_toast',
  not_enough_diamonds_30: 'not_enough_diamonds_cost'
};

let currentLang = 'en';

function detectInitialLanguage() {
  try {
    const saved = (typeof settings !== 'undefined' && settings.lang) ? settings.lang : localStorage.getItem('sectorDefenseTD_lang');
    if (saved && SUPPORTED_LANGUAGES[saved]) return saved;
    const nav = (navigator.language || navigator.userLanguage || 'en').toLowerCase();
    if (nav.startsWith('zh-tw') || nav.startsWith('zh-hk')) return 'tw';
    const short = nav.split('-')[0];
    if (SUPPORTED_LANGUAGES[short]) return short;
  } catch (e) {}
  return 'en';
}

function t(key, params) {
  const dict = I18N_DICT[currentLang] || I18N_DICT.en;
  const resolvedKey = (dict && dict[key] !== undefined) ? key : (KEY_ALIASES[key] || key);
  let str = (dict && dict[resolvedKey] !== undefined)
    ? dict[resolvedKey]
    : (I18N_DICT.en[resolvedKey] !== undefined ? I18N_DICT.en[resolvedKey] : '');

  if (!str) return '';

  const p = Object.assign({}, params);
  if (key === 'not_enough_diamonds_30' && p.cost === undefined) p.cost = 30;
  if (p.t !== undefined && p.n === undefined) p.n = p.t;
  if (p.n !== undefined && p.t === undefined) p.t = p.n;

  Object.keys(p).forEach(k => {
    str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), p[k]);
  });
  return str;
}

function applyStaticTranslations() {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = currentLang;
  document.documentElement.dir = (currentLang === 'ar') ? 'rtl' : 'ltr';

  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (key) {
      const val = t(key);
      if (val) el.textContent = val;
    }
  });

  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    if (key) {
      const val = t(key);
      if (val) el.innerHTML = val;
    }
  });
}

function setLanguage(langCode, persist = true) {
  if (!SUPPORTED_LANGUAGES[langCode]) langCode = 'en';
  currentLang = langCode;
  if (typeof settings !== 'undefined') settings.lang = langCode;
  if (persist) {
    try { localStorage.setItem('sectorDefenseTD_lang', langCode); } catch (e) {}
    if (typeof saveGameSoon === 'function') saveGameSoon();
  }
  applyStaticTranslations();

  const langSelect = document.getElementById('settingLangSelect');
  if (langSelect && langSelect.value !== langCode) {
    langSelect.value = langCode;
  }

  // Перерисовываем открытые динамические экраны и виджеты
  if (typeof window.__gameBooted !== 'undefined' && window.__gameBooted) {
    try {
      if (typeof updateUI === 'function') updateUI();
      if (typeof updateUpgradeButtonsLock === 'function') updateUpgradeButtonsLock();
      if (typeof updateBpProgressUI === 'function') updateBpProgressUI();
      if (typeof renderShopScreen === 'function' && gameState === 'SHOP') renderShopScreen();
      if (typeof renderUpgradeTree === 'function' && gameState === 'UPGRADES') renderUpgradeTree();
      if (typeof updateModeSwitcherUI === 'function' && gameState === 'LEVELS') {
        updateModeSwitcherUI();
        renderLevelsGrid();
      }
    } catch (e) {}
  }
}

function populateLanguageDropdown() {
  const select = document.getElementById('settingLangSelect');
  if (!select) return;
  select.innerHTML = '';
  Object.keys(SUPPORTED_LANGUAGES).forEach(code => {
    const opt = document.createElement('option');
    opt.value = code;
    opt.textContent = SUPPORTED_LANGUAGES[code];
    if (code === currentLang) opt.selected = true;
    select.appendChild(opt);
  });
}

window.t = t;
window.setLanguage = setLanguage;
window.applyStaticTranslations = applyStaticTranslations;
window.populateLanguageDropdown = populateLanguageDropdown;
window.detectInitialLanguage = detectInitialLanguage;